            MatrixUtils.mat4.rotateY(this.mMMatrix, this.mMMatrix, ry);
            MatrixUtils.mat4.rotateZ(this.mMMatrix, this.mMMatrix, rz);
            MatrixUtils.mat4.translate(this.mMMatrix, this.mMMatrix, [tx, ty, tz]);
