'use strict';

define(function() {

    function JsonDataLoader() {}

    /**
     * Static function to load binary data
     * @param  {string} url - URL for content
     * @param  {Function} - callback to receive binary data
     */
    JsonDataLoader.load = function(url, callback) {
        var root = this,
            xhr = new XMLHttpRequest();

        xhr.open('GET', url, true);
        xhr.responseType = 'json';
        xhr.onload = function() {
            callback && callback(this.response);
        };
        xhr.send(null);
    }

    return JsonDataLoader;
});

modules.framework/UncompressedTextureLoader:
'use strict';

define(function() {

    /**
     * Constructor. No need to create an instance of this class because it has only static methods
     */
    function UncompressedTextureLoader() {}

    /**
     * Loads texture from any image format supported by browser
     * @param  {string} url - URL to texture
     * @param  {Function} callbak - callback called after texture is loaded to GPU
     * @return {number} - WebGL texture
     */
    UncompressedTextureLoader.load = function(url, callback) {
            var texture = gl.createTexture();

            texture.image = new Image();
            texture.image.src = url;
            texture.image.onload = function() {
                gl.bindTexture(gl.TEXTURE_2D, texture);
                gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, texture.image);
                gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
                gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
                gl.bindTexture(gl.TEXTURE_2D, null);

                if (texture.image && texture.image.src) {
                    console.log('Loaded texture ' + url + ' [' + texture.image.width + 'x' + texture.image.height + ']');
                }

                callback && callback();
            };

            return texture;
        }

    return UncompressedTextureLoader;
});

modules.framework/utils/FullscreenUtils:
/**
 * @fileOverview Cross-browser full-screen utilities
 * @author Oleksandr Popov
 */

'use strict';

define(function() {

    function FullScreenUtils() {}

    /**
     * Enters fullscreen
     */
    FullScreenUtils.enterFullScreen = function() {
        if (document.documentElement.requestFullscreen) {
            if (!document.fullscreenElement) {
                document.documentElement.requestFullscreen();
            }
        }
        if (document.documentElement.webkitRequestFullScreen) {
            if (!document.webkitFullscreenElement) {
                document.documentElement.webkitRequestFullscreen();
            }
        }
        if (document.documentElement.mozRequestFullScreen) {
            if (!document.mozFullscreenElement) {
                document.documentElement.mozRequestFullScreen();
            }
        }
    }

    /**
     * Exits fullscreen
     */
    FullScreenUtils.exitFullScreen = function() {
        if (document.documentElement.requestFullscreen) {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
        if (document.documentElement.webkitRequestFullscreen) {
            if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            }
        }
        if (document.documentElement.mozRequestFullScreen) {
            if (document.mozCancelFullScreen) {
                document.mozCancelFullScreen();
            }
        }
    }

    /**
     * Adds cross-browser fullscreenchange event
     * @param {function} exitHandler - function to be called on fullscreenchange event
     */
    FullScreenUtils.addFullScreenListener = function(exitHandler) {
        if (document.documentElement.requestFullscreen) {
            document.addEventListener('fullscreenchange', exitHandler, false);
        }
        if (document.documentElement.webkitRequestFullScreen) {
            document.addEventListener('webkitfullscreenchange', exitHandler, false);
        }
        if (document.documentElement.mozRequestFullScreen) {
            document.addEventListener('mozfullscreenchange', exitHandler, false);
        }
    }

    /**
     * Checks fullscreen state
     * @return {Boolean} - true if fullscreen is active, false if not
     */
    FullScreenUtils.isFullScreen = function() {
        if (document.documentElement.requestFullscreen) {
            return !!document.fullscreenElement;
        }
        if (document.documentElement.webkitRequestFullscreen) {
            return !!document.webkitFullscreenElement;
        }
        if (document.documentElement.mozRequestFullScreen) {
            return !!document.mozFullScreenElement;
        }
    }

    /**
     * Checks for full-screen API availability
     * @return {Boolean} - true if fullscrees is supported, false if not
     */
    FullScreenUtils.isFullScreenSupported = function() {
        return !!document.documentElement.requestFullscreen || !!document.documentElement.webkitRequestFullScreen || !!document.documentElement.mozRequestFullScreen;
    }

    return FullScreenUtils;
});

